    coals:         { name: 'Coals', pro: true, colors: { bg:'#0a0605', surface:'#17100c', accent:'#e8791e', text:'#f2e2d4', border:'#2a1b12' } },
    virga:         { name: 'Virga', pro: true, colors: { bg:'#20222e', surface:'#2c2b38', accent:'#a8b2cc', text:'#e9e6ea', border:'#3b3946' } },
