      const g = cx.createRadialGradient(cv.width/2, cv.height*0.42, 0, cv.width/2, cv.height*0.42, Math.max(cv.width, cv.height));
      g.addColorStop(0, '#0f1c22'); g.addColorStop(1, '#060e12');
