        k.x += (Math.cos(k.a)*k.sp) * vellumDt; k.y += (Math.sin(k.a)*k.sp) * vellumDt;
        if (k.x < -40) k.x = cv.width+40; if (k.x > cv.width+40) k.x = -40;
        if (k.y < -40) k.y = cv.height+40; if (k.y > cv.height+40) k.y = -40;
