        cx.save(); cx.translate(ox, oy);
        cx.strokeStyle = 'rgba(150,170,200,0.22)'; cx.lineWidth = 1.4;
        cx.beginPath(); cx.arc(0, 0, c.R, 0, Math.PI * 2); cx.stroke();
        const gx = (c.R - c.r) * Math.cos(c.ang), gy = (c.R - c.r) * Math.sin(c.ang);
        cx.strokeStyle = 'rgba(190,210,240,0.40)';
        cx.beginPath(); cx.arc(gx, gy, c.r, 0, Math.PI * 2); cx.stroke();
        const P = pen(c.ang);
        cx.strokeStyle = 'rgba(230,240,255,0.55)'; cx.lineWidth = 1.2;
        cx.beginPath(); cx.moveTo(gx, gy); cx.lineTo(P.x, P.y); cx.stroke();
        cx.fillStyle = 'hsla(' + c.hue + ',90%,80%,0.95)';
        cx.beginPath(); cx.arc(P.x, P.y, 2.6, 0, Math.PI * 2); cx.fill();
        const gl = cx.createRadialGradient(P.x, P.y, 0, P.x, P.y, 26);
        gl.addColorStop(0, 'hsla(' + c.hue + ',90%,72%,0.35)'); gl.addColorStop(1, 'transparent');
        cx.fillStyle = gl; cx.fillRect(P.x - 26, P.y - 26, 52, 52);
